import OpenAI from "openai"
import { readFile } from "node:fs/promises"
import { Effect } from "effect"

const args = process.argv.slice(2)
const notesPath = args[0] ?? "CHANGELOG.md"
const apiKeyIndex = args.indexOf("--api-key")
const baseUrlIndex = args.indexOf("--base-url")
const apiKey = apiKeyIndex >= 0
  ? args[apiKeyIndex + 1]
  : process.env.OPENAI_API_KEY
const baseURL = baseUrlIndex >= 0
  ? args[baseUrlIndex + 1]
  : process.env.OPENAI_BASE_URL

const program = Effect.gen(function*() {
  const notes = yield* Effect.tryPromise(() => readFile(notesPath, "utf8"))
  const response = yield* Effect.tryPromise(() => {
    const client = new OpenAI({ apiKey, baseURL })
    return client.responses.create({
      model: "gpt-4.1-mini",
      instructions: "Summarize these release notes for application developers.",
      input: notes
    })
  })

  const summary = response.output_text.trim()
  if (summary.length === 0) {
    return yield* Effect.fail(new Error("The release summary was empty"))
  }
  yield* Effect.sync(() => process.stdout.write(`${summary}\n`))
})

Effect.runPromise(program).catch((error) => {
  console.error("Unable to summarize release notes:", error)
  process.exitCode = 1
})

